<?php require __DIR__.'/bootstrap.php';messenger_run(function($u){$cid=(int)($_GET['conversation_id']??0);MessengerSecurity::participant($cid,(int)$u['id']);return Database::fetchAll('SELECT l.id,l.user_id,u.name,l.latitude,l.longitude,l.accuracy_m,l.location_type,l.expires_at,l.stopped_at,l.updated_at FROM chat_live_locations l JOIN users u ON u.id=l.user_id WHERE l.conversation_id=? AND (l.location_type="fixed" OR (l.stopped_at IS NULL AND l.expires_at>NOW())) ORDER BY l.updated_at DESC LIMIT 100',[$cid]);});
